import type {CanonicalCommand,CanonicalPropertyNode} from "../data-layer-canonical-schema.js";
import type {CanonicalFocusedSectionContext} from "../data-layer-canonical-schema-focused-sections.js";
import {button,input,labeled} from "./dom.js";

export const applyStructure=(context:CanonicalFocusedSectionContext,command:CanonicalCommand):void=>{const result=context.command(command);if(result.status!=="applied"&&result.status!=="rebased")return;const selected=result.document.selectedPropertyId?result.document.nodes[result.document.selectedPropertyId]:undefined;context.select(result.document.selectedPropertyId);context.setWorking(selected?structuredClone(selected):undefined);context.render();};

export const renderCanonicalStructuralControls=(dom:Document,context:CanonicalFocusedSectionContext,working:CanonicalPropertyNode):HTMLElement[]=>{const document=context.current(),siblings=Object.values(document.nodes).filter(({parentId})=>parentId===working.parentId).sort((left,right)=>left.order-right.order||left.id.localeCompare(right.id)),index=siblings.findIndex(({id})=>id===working.id),earlier=button(dom,"Move earlier",()=>{if(index<=0)return;const afterId=index>1?siblings[index-2]!.id:undefined;applyStructure(context,{kind:"move",baseRevision:context.current().revision,propertyId:working.id,...(working.parentId?{parentId:working.parentId}:{}),...(afterId?{afterId}:{})});}),later=button(dom,"Move later",()=>{if(index<0||index>=siblings.length-1)return;applyStructure(context,{kind:"move",baseRevision:context.current().revision,propertyId:working.id,...(working.parentId?{parentId:working.parentId}:{}),afterId:siblings[index+1]!.id});}),toRoot=button(dom,"Move to root",()=>{if(!working.parentId)return;applyStructure(context,{kind:"move",baseRevision:context.current().revision,propertyId:working.id});}),duplicate=button(dom,"Duplicate",()=>applyStructure(context,{kind:"duplicate",baseRevision:context.current().revision,propertyId:working.id,id:context.id})),remove=button(dom,"Delete property",()=>applyStructure(context,{kind:"delete",baseRevision:context.current().revision,propertyId:working.id}));earlier.disabled=index<=0;later.disabled=index<0||index>=siblings.length-1;toRoot.disabled=!working.parentId;return[earlier,later,toRoot,duplicate,remove];};

export function renderStructureFacet(host:HTMLElement,context:CanonicalFocusedSectionContext,working:CanonicalPropertyNode):void {
  const {dom}=context;host.append(Object.assign(dom.createElement("p"),{textContent:`Stable identity ${working.id} · ${context.current().id}`}),labeled(dom,"Name",input(dom,"structureName",working.name)),button(dom,"Add child",()=>applyStructure(context,{kind:"add",baseRevision:context.current().revision,parentId:working.id,name:"child",type:"string",id:context.id})),button(dom,"Add sibling",()=>applyStructure(context,{kind:"add",baseRevision:context.current().revision,...(working.parentId?{parentId:working.parentId}:{}),afterId:working.id,name:"property",type:"string",id:context.id})),...renderCanonicalStructuralControls(dom,context,working));
}
